alter table public.quiz_questions
  drop constraint if exists quiz_questions_category_check;

alter table public.quiz_questions
  add constraint quiz_questions_category_check
  check (category in ('pedagogica', 'especificos', 'razonamiento', 'ofimatica'));

with base_sequence as (
  select coalesce(max(sequence), 0) + 1000 as value
  from public.quiz_questions
),
